<?php
class AuthController {
 private Auth $auth; public function __construct(){ $this->auth=new Auth(); }
 public function login(){ if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); if($this->auth->login(trim($_POST['email']??''),$_POST['password']??'')){ flash('¡Qué bueno tenerte de vuelta!'); redirect('inicio'); } flash('Correo o contraseña incorrectos, o cuenta inactiva.','error'); redirect('login'); } require __DIR__.'/../views/auth/login.php'; }
 public function register(){ if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $name=trim($_POST['name']??''); $email=strtolower(trim($_POST['email']??'')); $pass=$_POST['password']??''; if($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($pass)<8){ flash('Revisa los datos. La contraseña debe tener mínimo 8 caracteres.','error'); redirect('registro'); } try{$this->auth->register($name,$email,$pass); flash('Cuenta creada. Ya puedes iniciar sesión.'); redirect('login');}catch(PDOException $e){ flash('Ese correo ya está registrado.','error'); redirect('registro');} } require __DIR__.'/../views/auth/register.php'; }
 public function forgot(){ if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $u=$this->auth->findByEmail(trim($_POST['email']??'')); if($u){ $_SESSION['reset_user_id']=$u['id']; flash('Cuenta encontrada. Crea una nueva contraseña para continuar.'); redirect('restablecer'); } flash('Si el correo existe, podrás continuar con la recuperación.','error'); redirect('recuperar'); } require __DIR__.'/../views/auth/forgot.php'; }
 public function reset(){ if(empty($_SESSION['reset_user_id'])) redirect('recuperar'); if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $pass=$_POST['password']??''; if(strlen($pass)<8){flash('Usa al menos 8 caracteres.','error');redirect('restablecer');} $this->auth->resetPassword((int)$_SESSION['reset_user_id'],$pass); unset($_SESSION['reset_user_id']); flash('Contraseña actualizada. Inicia sesión.'); redirect('login'); } require __DIR__.'/../views/auth/reset.php'; }
 public function logout(){ session_destroy(); header('Location: '.BASE_URL.'/?page=login'); exit; }
}
